// Some portions generated by Codex
package org.eclipse.rdf4j.http.server.repository.transaction;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.repository.Repository;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import com.sun.net.httpserver.HttpServer;

class ServerTransactionOutboundResourceAccessTest {

	@TempDir
	Path temporaryDirectory;

	@Test
	void transactionLoadDoesNotReadLocalFile() throws Exception {
		Path localRdf = temporaryDirectory.resolve("private.ttl");
		Files.writeString(localRdf, "<urn:secret> <urn:predicate> <urn:value> .\n");
		Repository repository = new SailRepository(new MemoryStore());
		repository.init();
		try {
			try (Transaction transaction = new Transaction(repository)) {
				transaction.begin();
				assertThatThrownBy(() -> transaction.executeUpdate(QueryLanguage.SPARQL,
						"LOAD <" + localRdf.toUri() + ">", null, false, null, Map.of()))
								.hasStackTraceContaining("Remote RDF resource denied");
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void transactionServiceDoesNotContactLoopbackEndpoint() throws Exception {
		AtomicInteger requests = new AtomicInteger();
		HttpServer endpoint = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		endpoint.createContext("/sparql", exchange -> {
			requests.incrementAndGet();
			byte[] response = "{\"head\":{\"vars\":[]},\"results\":{\"bindings\":[]}}"
					.getBytes(StandardCharsets.UTF_8);
			exchange.getResponseHeaders().set("Content-Type", "application/sparql-results+json");
			exchange.sendResponseHeaders(200, response.length);
			try (var output = exchange.getResponseBody()) {
				output.write(response);
			}
		});
		endpoint.start();
		Repository repository = new SailRepository(new MemoryStore());
		repository.init();
		try {
			String service = "http://127.0.0.1:" + endpoint.getAddress().getPort() + "/sparql";
			try (Transaction transaction = new Transaction(repository)) {
				transaction.begin();
				assertThatThrownBy(() -> transaction.executeUpdate(QueryLanguage.SPARQL,
						"INSERT { ?s ?p ?o } WHERE { SERVICE <" + service + "> { ?s ?p ?o } }", null, false,
						null, Map.of()))
								.hasStackTraceContaining("SERVICE endpoint denied");
				assertThat(requests).hasValue(0);
			}
		} finally {
			repository.shutDown();
			endpoint.stop(0);
		}
	}
}
